(()=>{const isPassword=input=>input instanceof HTMLInputElement&&(input.type==='password'||input.dataset.passwordField!==undefined||/password/.test(input.name));const note=input=>{input.dataset.passwordField='';let text=input.closest('.customer-password-field,.admin-auth-field,label')?.querySelector('.password-policy-note');if(!text){text=document.createElement('small');text.className='password-policy-note';text.setAttribute('role','status');(input.closest('.customer-password-field,.admin-auth-field')||input.parentElement).append(text)}text.textContent='حروف إنجليزية وأرقام ورموز فقط، دون العربية أو المسافات.';};document.addEventListener('beforeinput',e=>{if(isPassword(e.target)&&e.data&&/[^!-~]/.test(e.data)){e.preventDefault();note(e.target)}});document.addEventListener('input',e=>{if(!isPassword(e.target))return;const input=e.target;input.dataset.passwordField='';if(/[^!-~]/.test(input.value)){input.value=input.value.replace(/[^!-~]/g,'');note(input)}input.setCustomValidity(input.value&&input.value.length<6?'كلمة المرور 6 محارف على الأقل.':'')});document.addEventListener('paste',e=>{if(isPassword(e.target)&&/[^!-~]/.test(e.clipboardData?.getData('text')||'')){e.preventDefault();note(e.target)}});})();
